"""Piecewise capture stream and the HTTP/1.1 origin framing reader.

A channel is a concatenation of compressed parts, so the reader materialises
only small line windows and skips declared bodies by length arithmetic; body
fingerprints come from compressed range hashing.
"""
from bisect import bisect_right

from modules.byte_program import MAX, Lit, hash_range, read

LINE_CONTENT_MAX = 8192
LINE_WINDOW = LINE_CONTENT_MAX + 2
BLOCK_BYTES_MAX = 65536
BLOCK_FIELDS_MAX = 128
TRAILER_BYTES_MAX = 65536
TRAILER_FIELDS_MAX = 128
READ_AHEAD = LINE_WINDOW

TOKEN = frozenset(b"!#$%&'*+-.^_`|~0123456789"
                  b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ")
FORBIDDEN_TRAILERS = frozenset((b'host', b'content-length', b'transfer-encoding'))

OK = 'ok'
INCOMPLETE = 'incomplete'
SYNTAX = 'syntax'

VALUE_TABLE = bytes((0 if (byte == 9 or 32 <= byte <= 126) else 1)
                    for byte in range(256))
VISIBLE_TABLE = bytes((0 if 33 <= byte <= 126 else 1) for byte in range(256))
HEX_TABLE = bytes((0 if chr(byte) in '0123456789abcdefABCDEF' else 1)
                  for byte in range(256))


class FramingError(Exception):
    def __init__(self, kind):
        super().__init__(kind)
        self.kind = kind


class BudgetExceeded(Exception):
    pass


class Counters:
    """Input-domain budgets on examined origin requests and chunk-size lines."""

    __slots__ = ('requests', 'chunk_lines')

    def __init__(self):
        self.requests = 0
        self.chunk_lines = 0


class Capture:
    """Byte stream assembled from attributed compressed parts."""

    def __init__(self, parts):
        self.owners = []
        self.nodes = []
        starts = [0]
        total = 0
        for owner, node in parts:
            if node.length:
                self.owners.append(owner)
                self.nodes.append(node)
                total += node.length
                starts.append(total)
        self.starts = starts
        self.length = total
        self._buf = b''
        self._buf_start = 0
        self._buf_end = 0
        self._cursor = 0

    def total(self):
        return self.length

    def fingerprint(self):
        """Fingerprint of the complete concatenated capture."""
        length = 0
        digest = 0
        for node in self.nodes:
            if node.length:
                digest = (digest * pow_span(node.length) + node.hash) & (2**64 - 1)
                length += node.length
        from modules.byte_program import hexdigest
        return {'n': length, 'h': hexdigest(digest)}

    def read(self, offset, size):
        if size <= 0 or offset >= self.length:
            return b''
        end = offset + size
        if size <= READ_AHEAD and offset >= self._buf_start and end <= self._buf_end:
            return self._buf[offset - self._buf_start:end - self._buf_start]
        window = min(self.length, offset + (size if size > READ_AHEAD else READ_AHEAD))
        self._buf = read(self.nodes[index_of(self.starts, offset)],
                         offset - self.starts[index_of(self.starts, offset)],
                         0) if False else None
        block = self._materialize(offset, window)
        if size <= READ_AHEAD:
            self._buf = block
            self._buf_start = offset
            self._buf_end = offset + len(block)
            return block[:size]
        return block[:size]

    def _materialize(self, offset, end):
        out = bytearray()
        pos = offset
        index = index_of(self.starts, offset)
        total = self.length
        while pos < end and index < len(self.nodes):
            base = self.starts[index]
            stop = min(end, self.starts[index + 1], total)
            if stop > pos:
                out += read(self.nodes[index], pos - base, stop - base)
                pos = stop
            index += 1
        return bytes(out)

    def hash_span(self, lo, hi):
        """Exact fingerprint hash of the byte range [lo, hi)."""
        if hi <= lo:
            return 0
        if lo == 0 and hi == self.length:
            return self.fingerprint_hash()
        result = 0
        pos = lo
        index = index_of(self.starts, lo)
        total = self.length
        while pos < hi and index < len(self.nodes):
            base = self.starts[index]
            stop = min(hi, self.starts[index + 1], total)
            if stop > pos:
                piece = hash_range(self.nodes[index], pos - base, stop - base)
                result = (result * pow_span(stop - pos) + piece) & (2**64 - 1)
                pos = stop
            index += 1
        return result

    def fingerprint_hash(self):
        length = 0
        digest = 0
        for node in self.nodes:
            if node.length:
                digest = (digest * pow_span(node.length) + node.hash) & (2**64 - 1)
                length += node.length
        return digest

    def reset_cursor(self):
        self._cursor = 0

    def attribute(self, start, end):
        """First-byte owner plus merged [label, byte count] attribution."""
        index = self._cursor
        total_parts = len(self.nodes)
        if index >= total_parts or self.starts[index] > start \
                or self.starts[index + 1] <= start:
            index = index_of(self.starts, start)
        self._cursor = index
        counts = {}
        covered = 0
        target = end - start
        position = index
        while position < total_parts and covered < target \
                and self.starts[position] < end:
            base = self.starts[position]
            stop = min(end, self.starts[position + 1])
            span = stop - max(start, base)
            if span > 0:
                label = self.owners[position]
                counts[label] = counts.get(label, 0) + span
                covered += span
            position += 1
        owner = self.owners[index] if index < total_parts else None
        return owner, list(counts.items())


def index_of(starts, offset):
    """Index of the part holding byte offset (starts is strictly increasing)."""
    index = bisect_right(starts, offset) - 1
    if index < 0:
        index = 0
    while index + 1 < len(starts) and starts[index + 1] <= offset:
        index += 1
    return index


_POW = {}


def pow_span(exponent):
    got = _POW.get(exponent)
    if got is None:
        got = pow(257, exponent, 1 << 64)
        if len(_POW) > 8192:
            _POW.clear()
        _POW[exponent] = got
    return got


def read_line(capture, pos):
    """Read one CRLF terminated line, applying the documented line policy."""
    remaining = capture.length - pos
    probe = 64
    while True:
        size = probe if remaining > probe else remaining
        window = capture.read(pos, size)
        found = window.find(b'\n')
        if found >= 0:
            if found == 0 or window[found - 1] != 13:
                return None, SYNTAX
            return window[:found - 1], OK
        if size >= remaining:
            return None, (INCOMPLETE if remaining <= LINE_CONTENT_MAX + 1 else SYNTAX)
        if size >= LINE_WINDOW:
            return None, SYNTAX
        probe = 512 if probe < 512 else LINE_WINDOW


def parse_field_line(line):
    found = line.find(b':')
    if found <= 0:
        raise FramingError(SYNTAX)
    name = line[:found]
    raw = line[found + 1:]
    for byte in name:
        if byte not in TOKEN:
            raise FramingError(SYNTAX)
    if b'\x01' in raw.translate(VALUE_TABLE):
        raise FramingError(SYNTAX)
    return name, raw.strip(b' \t')


def parse_request_line(line):
    parts = line.split(b' ')
    if len(parts) != 3:
        raise FramingError(SYNTAX)
    method, target, version = parts
    if not method:
        raise FramingError(SYNTAX)
    for byte in method:
        if byte not in TOKEN:
            raise FramingError(SYNTAX)
    if not target or b'\x01' in target.translate(VISIBLE_TABLE):
        raise FramingError(SYNTAX)
    if version != b'HTTP/1.1':
        raise FramingError(SYNTAX)
    return method, target


def parse_content_length(value):
    """Declared length members of one Content-Length occurrence."""
    members = []
    for member in value.split(b','):
        member = member.strip(b' \t')
        if not member or b'\x01' in member.translate(HEX_TABLE):
            raise FramingError(SYNTAX)
        number = 0
        for byte in member:
            number = number * 10 + (byte - 48)
            if number > MAX:
                raise FramingError(SYNTAX)
        members.append(number)
    if not members:
        raise FramingError(SYNTAX)
    return members


def parse_chunk_size(line):
    found = line.find(b';')
    if found >= 0:
        size_part = line[:found]
        if b'\x01' in line[found + 1:].translate(VALUE_TABLE):
            raise FramingError(SYNTAX)
    else:
        size_part = line
    if not size_part or b'\x01' in size_part.translate(HEX_TABLE):
        raise FramingError(SYNTAX)
    value = int(size_part, 16)
    if value > MAX:
        raise FramingError(SYNTAX)
    return value


def parse_header_block(capture, pos, counters):
    """Read the request line plus field block; returns fields and new offset."""
    fields = []
    block = 0
    line, status = read_line(capture, pos)
    if status != OK:
        raise FramingError(status)
    block += len(line) + 2
    if block > BLOCK_BYTES_MAX:
        raise FramingError(SYNTAX)
    method, target = parse_request_line(line)
    pos += len(line) + 2
    host_value = None
    while True:
        line, status = read_line(capture, pos)
        if status != OK:
            raise FramingError(status)
        block += len(line) + 2
        if block > BLOCK_BYTES_MAX:
            raise FramingError(SYNTAX)
        if not line:
            pos += 2
            return fields, method, target, host_value, pos, block
        if len(fields) >= BLOCK_FIELDS_MAX:
            raise FramingError(SYNTAX)
        name, value = parse_field_line(line)
        lowered = name.lower()
        if lowered == b'host':
            host_value = value
        fields.append((name, value))
        pos += len(line) + 2


def parse_framing(fields):
    """Classify framing and validate Content-Length / Transfer-Encoding rules."""
    lengths = []
    chunked = 0
    for name, value in fields:
        lowered = name.lower()
        if lowered == b'content-length':
            lengths.extend(parse_content_length(value))
        elif lowered == b'transfer-encoding':
            chunked += 1
            if value.lower() != b'chunked':
                raise FramingError(SYNTAX)
    if chunked > 1 or (chunked and lengths):
        raise FramingError(SYNTAX)
    if lengths:
        first = lengths[0]
        for other in lengths:
            if other != first:
                raise FramingError(SYNTAX)
        return 'length', first
    if chunked:
        return 'chunked', None
    return 'none', None


def parse_body(capture, pos, framing, declared, counters):
    """Consume the declared body; returns a body mixer hash pair and offset."""
    from modules.byte_program import Mixer
    mixer = Mixer()
    length = capture.length
    if framing == 'length':
        if declared:
            if pos + declared > length:
                raise FramingError(INCOMPLETE)
            mixer.add_hash(declared, capture.hash_span(pos, pos + declared))
            pos += declared
        return mixer, pos
    if framing == 'none':
        return mixer, pos
    while True:
        line, status = read_line(capture, pos)
        if status != OK:
            raise FramingError(status)
        counters.chunk_lines += 1
        if counters.chunk_lines > 40000:
            raise BudgetExceeded('chunk size lines')
        size = parse_chunk_size(line)
        pos += len(line) + 2
        if size == 0:
            trailers = []
            block = 0
            while True:
                line, status = read_line(capture, pos)
                if status != OK:
                    raise FramingError(status)
                if not line:
                    block += 2
                    if block > TRAILER_BYTES_MAX:
                        raise FramingError(SYNTAX)
                    pos += 2
                    return mixer, trailers, pos
                block += len(line) + 2
                if block > TRAILER_BYTES_MAX:
                    raise FramingError(SYNTAX)
                if len(trailers) >= TRAILER_FIELDS_MAX:
                    raise FramingError(SYNTAX)
                name, value = parse_field_line(line)
                if name.lower() in FORBIDDEN_TRAILERS:
                    raise FramingError(SYNTAX)
                trailers.append((name, value))
                pos += len(line) + 2
        if pos + size > length:
            raise FramingError(INCOMPLETE)
        mixer.add_hash(size, capture.hash_span(pos, pos + size))
        pos += size
        if length - pos < 2:
            raise FramingError(INCOMPLETE)
        if capture.read(pos, 2) != b'\r\n':
            raise FramingError(SYNTAX)
        pos += 2


def parse_request(capture, pos, counters):
    """Parse one complete request; returns the raw record and the end offset."""
    from modules.byte_program import Mixer, fingerprint_bytes
    start = pos
    fields, method, target, host_value, pos, block = parse_header_block(
        capture, pos, counters)
    framing, declared = parse_framing(fields)
    if framing == 'chunked':
        body, trailers, pos = parse_body(capture, pos, framing, declared, counters)
    else:
        body, pos = parse_body(capture, pos, framing, declared, counters)
        trailers = []
    counters.requests += 1
    if counters.requests > 20000:
        raise BudgetExceeded('origin requests')
    headers = Mixer()
    write_block = headers
    from modules.byte_program import write_field_block
    write_field_block(write_block, [(name, value) for name, value in fields])
    trailer_block = Mixer()
    write_field_block(trailer_block, trailers)
    host_count = sum(1 for name, _ in fields if name.lower() == b'host')
    return {
        'start': start,
        'end': pos,
        'method': method,
        'target': target,
        'host': host_value.lower() if host_count == 1 else b'',
        'host_count': host_count,
        'headers': headers.result(),
        'body': body.result(),
        'trailers': trailer_block.result(),
        'framing': framing,
    }, pos


def parse_channel(capture, counters):
    """Parse consecutive requests, stopping at the first framing failure."""
    from modules.byte_program import Lit
    requests = []
    error = None
    pos = 0
    while True:
        if pos >= capture.length:
            break
        start = pos
        try:
            record, pos = parse_request(capture, pos, counters)
        except FramingError as exc:
            error = {'kind': exc.kind, 'offset': start}
            break
        requests.append(record)
    return requests, error
